def min_moves_optimal(n, a, b):
    if a == b:
        return 0

    a_chars = set(a)
    target_chars = set()

    for i in range(n):
        if a[i] != b[i]:
            target_chars.add(b[i])

    # Check if conversion is possible
    for ch in target_chars:
        if ch not in a_chars:
            return -1

    return len(target_chars)

# Input
n = int(input())
a = input()
b = input()
print(min_moves_optimal(n, a, b))

