def longest_common_prefix(strs):
    if not strs:
        return ""

    prefix = ""
    first = strs[0]

    for i in range(len(first)):
        c = first[i]
        for s in strs[1:]:
            if i >= len(s) or s[i] != c:
                return prefix
        prefix += c

    return prefix

# Input
n = int(input())
strs = [input() for _ in range(n)]
print(longest_common_prefix(strs))

def max_occupied_row_brute(matrix, r, c):
    max_count = -1
    result_row = -1

    for i in range(r):
        count = 0
        for j in range(c):
            if matrix[i][j] == 1:
                count += 1
        if count > max_count:
            max_count = count
            result_row = i + 1  # 1-indexed

    return result_row

# Input
r, c = map(int, input().split())
matrix = []
for _ in range(r):
    row = list(map(int, input().split()))
    matrix.append(row)
print(max_occupied_row_brute(matrix, r, c))

