import heapq

def dijkstra(n, edges, src, dest):
    # Build adjacency list
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))  # undirected

    # Dijkstra's algorithm
    dist = {i: float('inf') for i in range(1, n + 1)}
    parent = {i: -1 for i in range(1, n + 1)}
    dist[src] = 0

    heap = [(0, src)]  # (distance, node)

    while heap:
        d, u = heapq.heappop(heap)

        if d > dist[u]:
            continue  # skip outdated entries

        if u == dest:
            break  # found shortest to dest

        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                parent[v] = u
                heapq.heappush(heap, (dist[v], v))

    # Reconstruct path
    if dist[dest] == float('inf'):
        print('No path exists')
        return

    path = []
    node = dest
    while node != -1:
        path.append(node)
        node = parent[node]
    path.reverse()

    print('Path:', ' -> '.join(map(str, path)))
    print('Distance:', dist[dest])

# Input
n, m = map(int, input().split())
edges = []
for _ in range(m):
    u, v, w = map(int, input().split())
    edges.append((u, v, w))
src, dest = map(int, input().split())
dijkstra(n, edges, src, dest)
